// A JNA Library to expose the extern-C FFI definitions.
// This is an implementation detail which will be called internally by the public API.

internal interface UniffiLib : Library {
    companion object {
        internal val INSTANCE: UniffiLib by lazy {
            loadIndirect<UniffiLib>(componentName = "vauchi_platform")
                .also { lib: UniffiLib ->
                    uniffiCheckContractApiVersion(lib)
                    uniffiCheckApiChecksums(lib)
                    uniffiCallbackInterfaceMobileBleDelegate.register(lib)
                    uniffiCallbackInterfaceMobileNfcTransport.register(lib)
                    uniffiCallbackInterfaceMobilePlatformKeychain.register(lib)
                    uniffiCallbackInterfaceMobileProximityHandler.register(lib)
                    uniffiCallbackInterfaceMobileWifiAwareHandler.register(lib)
                    uniffiCallbackInterfacePlatformAudioHandler.register(lib)
                }
        }

        // The Cleaner for the whole library
        internal val CLEANER: UniffiCleaner by lazy {
            UniffiCleaner.create()
        }
    }

