/**
 * Unified navigation and screen engine for mobile/desktop platforms.
 *
 * Wraps `AppEngine` with JSON-based FFI transport.
 * Manages screen navigation, engine lifecycle, and form dialog persistence.
 *
 * # Usage from Swift/Kotlin
 *
 * ```swift
 * let engine = try PlatformAppEngine(
 * dataDir: dataDir,
 * relayUrl: "wss://relay.vauchi.app",
 * storageKeyBytes: keyBytes
 * )
 *
 * // Get current screen
 * let screenJson = try engine.currentScreenJson()
 *
 * // Handle user action
 * let resultJson = try engine.handleActionJson(
 * actionJson: "{\"ActionPressed\": {\"action_id\": \"get_started\"}}"
 * )
 *
 * // Navigate to a screen
 * let screenJson = try engine.navigateToJson(screenJson: "\"Exchange\"")
 *
 * // After VauchiPlatform mutations, invalidate
 * try engine.invalidateAll()
 * ```
 */
public interface PlatformAppEngineInterface {
    /**
     * Returns the available navigation screens as a JSON array.
     *
     * These are the screens that should appear in the navigation bar/tabs.
     */
    fun `availableScreensJson`(): kotlin.String

    /**
     * Returns the current screen's screen_id (lightweight query).
     *
     * Useful for tab bar highlighting without deserializing the full ScreenModel.
     */
    fun `currentScreenId`(): kotlin.String

    /**
     * Returns the current screen as a JSON string.
     *
     * The JSON structure matches `ScreenModel` from vauchi-core.
     */
    fun `currentScreenJson`(): kotlin.String

    /**
     * Returns the default landing screen as a JSON string.
     *
     * Returns MyInfo when no contacts, Contacts when >=1 contact.
     */
    fun `defaultScreenJson`(): kotlin.String

    /**
     * Returns whether the current form has unsaved user data.
     *
     * Used by frontends to show a "discard changes?" prompt on back navigation.
     */
    fun `formHasData`(): kotlin.Boolean

    /**
     * Handles a user action (as JSON) and returns the result as JSON.
     *
     * The action JSON must match the `UserAction` enum format.
     * The result JSON matches the `ActionResult` enum.
     */
    fun `handleActionJson`(`actionJson`: kotlin.String): kotlin.String

    /**
     * Returns whether the user has created an identity.
     *
     * Used by frontends to decide between onboarding and main UI.
     */
    fun `hasIdentity`(): kotlin.Boolean

    /**
     * Invalidate all cached engines.
     *
     * Call this after mutations via `VauchiPlatform` so the next
     * `current_screen_json()` rebuilds engines with fresh data.
     */
    fun `invalidateAll`()

    /**
     * Invalidate a specific screen's cached engine.
     *
     * The screen JSON must match the `AppScreen` enum format.
     */
    fun `invalidateScreenJson`(`screenJson`: kotlin.String)

    /**
     * Navigate back in the history stack.
     *
     * Returns the previous screen model as JSON.
     */
    fun `navigateBackJson`(): kotlin.String

    /**
     * Navigate to a screen (as JSON) and return the new screen model as JSON.
     *
     * The screen JSON must match the `AppScreen` enum format, e.g.:
     * - `"Exchange"` (simple variant)
     * - `{"ContactDetail": {"contact_id": "abc"}}` (parameterized variant)
     */
    fun `navigateToJson`(`screenJson`: kotlin.String): kotlin.String

    /**
     * Report device hardware capabilities.
     *
     * Call once at startup after querying platform hardware APIs.
     * Determines which exchange modes are available.
     */
    fun `setDeviceCapabilitiesJson`(`capabilitiesJson`: kotlin.String)

    companion object
}

/**
 * Unified navigation and screen engine for mobile/desktop platforms.
 *
 * Wraps `AppEngine` with JSON-based FFI transport.
 * Manages screen navigation, engine lifecycle, and form dialog persistence.
 *
 * # Usage from Swift/Kotlin
 *
 * ```swift
 * let engine = try PlatformAppEngine(
 * dataDir: dataDir,
 * relayUrl: "wss://relay.vauchi.app",
 * storageKeyBytes: keyBytes
 * )
 *
 * // Get current screen
 * let screenJson = try engine.currentScreenJson()
 *
 * // Handle user action
 * let resultJson = try engine.handleActionJson(
 * actionJson: "{\"ActionPressed\": {\"action_id\": \"get_started\"}}"
 * )
 *
 * // Navigate to a screen
 * let screenJson = try engine.navigateToJson(screenJson: "\"Exchange\"")
 *
 * // After VauchiPlatform mutations, invalidate
 * try engine.invalidateAll()
 * ```
 */
open class PlatformAppEngine :
    Disposable,
    AutoCloseable,
    PlatformAppEngineInterface {
    constructor(pointer: Pointer) {
        this.pointer = pointer
        this.cleanable = UniffiLib.CLEANER.register(this, UniffiCleanAction(pointer))
    }

    /**
     * This constructor can be used to instantiate a fake object. Only used for tests. Any
     * attempt to actually use an object constructed this way will fail as there is no
     * connected Rust object.
     */
    @Suppress("UNUSED_PARAMETER")
    constructor(noPointer: NoPointer) {
        this.pointer = null
        this.cleanable = UniffiLib.CLEANER.register(this, UniffiCleanAction(pointer))
    }

    /**
     * Create a new PlatformAppEngine with platform-provided secure key.
     *
     * This creates its own `Vauchi` instance backed by the same database
     * as `VauchiPlatform`. After mutations via `VauchiPlatform`, call
     * `invalidate_all()` to refresh cached engines.
     */
    constructor(`dataDir`: kotlin.String, `relayUrl`: kotlin.String, `storageKeyBytes`: kotlin.ByteArray) :
        this(
            uniffiRustCallWithError(MobileException) { _status ->
                UniffiLib.INSTANCE.uniffi_vauchi_platform_fn_constructor_platformappengine_new(
                    FfiConverterString.lower(`dataDir`),
                    FfiConverterString.lower(`relayUrl`),
                    FfiConverterByteArray.lower(`storageKeyBytes`),
                    _status,
                )
            },
        )

    protected val pointer: Pointer?
    protected val cleanable: UniffiCleaner.Cleanable

    private val wasDestroyed = AtomicBoolean(false)
    private val callCounter = AtomicLong(1)

    override fun destroy() {
        // Only allow a single call to this method.
        // TODO: maybe we should log a warning if called more than once?
        if (this.wasDestroyed.compareAndSet(false, true)) {
            // This decrement always matches the initial count of 1 given at creation time.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable.clean()
            }
        }
    }

    @Synchronized
    override fun close() {
        this.destroy()
    }

    internal inline fun <R> callWithPointer(block: (ptr: Pointer) -> R): R {
        // Check and increment the call counter, to keep the object alive.
        // This needs a compare-and-set retry loop in case of concurrent updates.
        do {
            val c = this.callCounter.get()
            if (c == 0L) {
                throw IllegalStateException("${this.javaClass.simpleName} object has already been destroyed")
            }
            if (c == Long.MAX_VALUE) {
                throw IllegalStateException("${this.javaClass.simpleName} call counter would overflow")
            }
        } while (!this.callCounter.compareAndSet(c, c + 1L))
        // Now we can safely do the method call without the pointer being freed concurrently.
        try {
            return block(this.uniffiClonePointer())
        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable.clean()
            }
        }
    }

    // Use a static inner class instead of a closure so as not to accidentally
    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(
        private val pointer: Pointer?,
    ) : Runnable {
        override fun run() {
            pointer?.let { ptr ->
                uniffiRustCall { status ->
                    UniffiLib.INSTANCE.uniffi_vauchi_platform_fn_free_platformappengine(ptr, status)
                }
            }
        }
    }

    fun uniffiClonePointer(): Pointer =
        uniffiRustCall { status ->
            UniffiLib.INSTANCE.uniffi_vauchi_platform_fn_clone_platformappengine(pointer!!, status)
        }

    /**
     * Returns the available navigation screens as a JSON array.
     *
     * These are the screens that should appear in the navigation bar/tabs.
     */
    @Throws(MobileException::class)
    override fun `availableScreensJson`(): kotlin.String =
        FfiConverterString.lift(
            callWithPointer {
                uniffiRustCallWithError(MobileException) { _status ->
                    UniffiLib.INSTANCE.uniffi_vauchi_platform_fn_method_platformappengine_available_screens_json(it, _status)
                }
            },
        )

    /**
     * Returns the current screen's screen_id (lightweight query).
     *
     * Useful for tab bar highlighting without deserializing the full ScreenModel.
     */
    @Throws(MobileException::class)
    override fun `currentScreenId`(): kotlin.String =
        FfiConverterString.lift(
            callWithPointer {
                uniffiRustCallWithError(MobileException) { _status ->
                    UniffiLib.INSTANCE.uniffi_vauchi_platform_fn_method_platformappengine_current_screen_id(it, _status)
                }
            },
        )

    /**
     * Returns the current screen as a JSON string.
     *
     * The JSON structure matches `ScreenModel` from vauchi-core.
     */
    @Throws(MobileException::class)
    override fun `currentScreenJson`(): kotlin.String =
        FfiConverterString.lift(
            callWithPointer {
                uniffiRustCallWithError(MobileException) { _status ->
                    UniffiLib.INSTANCE.uniffi_vauchi_platform_fn_method_platformappengine_current_screen_json(it, _status)
                }
            },
        )

    /**
     * Returns the default landing screen as a JSON string.
     *
     * Returns MyInfo when no contacts, Contacts when >=1 contact.
     */
    @Throws(MobileException::class)
    override fun `defaultScreenJson`(): kotlin.String =
        FfiConverterString.lift(
            callWithPointer {
                uniffiRustCallWithError(MobileException) { _status ->
                    UniffiLib.INSTANCE.uniffi_vauchi_platform_fn_method_platformappengine_default_screen_json(it, _status)
                }
            },
        )

    /**
     * Returns whether the current form has unsaved user data.
     *
     * Used by frontends to show a "discard changes?" prompt on back navigation.
     */
    @Throws(MobileException::class)
    override fun `formHasData`(): kotlin.Boolean =
        FfiConverterBoolean.lift(
            callWithPointer {
                uniffiRustCallWithError(MobileException) { _status ->
                    UniffiLib.INSTANCE.uniffi_vauchi_platform_fn_method_platformappengine_form_has_data(it, _status)
                }
            },
        )

    /**
     * Handles a user action (as JSON) and returns the result as JSON.
     *
     * The action JSON must match the `UserAction` enum format.
     * The result JSON matches the `ActionResult` enum.
     */
    @Throws(MobileException::class)
    override fun `handleActionJson`(`actionJson`: kotlin.String): kotlin.String =
        FfiConverterString.lift(
            callWithPointer {
                uniffiRustCallWithError(MobileException) { _status ->
                    UniffiLib.INSTANCE.uniffi_vauchi_platform_fn_method_platformappengine_handle_action_json(
                        it,
                        FfiConverterString.lower(`actionJson`),
                        _status,
                    )
                }
            },
        )

    /**
     * Returns whether the user has created an identity.
     *
     * Used by frontends to decide between onboarding and main UI.
     */
    @Throws(MobileException::class)
    override fun `hasIdentity`(): kotlin.Boolean =
        FfiConverterBoolean.lift(
            callWithPointer {
                uniffiRustCallWithError(MobileException) { _status ->
                    UniffiLib.INSTANCE.uniffi_vauchi_platform_fn_method_platformappengine_has_identity(it, _status)
                }
            },
        )

    /**
     * Invalidate all cached engines.
     *
     * Call this after mutations via `VauchiPlatform` so the next
     * `current_screen_json()` rebuilds engines with fresh data.
     */
    @Throws(MobileException::class)
    override fun `invalidateAll`() =
        callWithPointer {
            uniffiRustCallWithError(MobileException) { _status ->
                UniffiLib.INSTANCE.uniffi_vauchi_platform_fn_method_platformappengine_invalidate_all(it, _status)
            }
        }

    /**
     * Invalidate a specific screen's cached engine.
     *
     * The screen JSON must match the `AppScreen` enum format.
     */
    @Throws(MobileException::class)
    override fun `invalidateScreenJson`(`screenJson`: kotlin.String) =
        callWithPointer {
            uniffiRustCallWithError(MobileException) { _status ->
                UniffiLib.INSTANCE.uniffi_vauchi_platform_fn_method_platformappengine_invalidate_screen_json(
                    it,
                    FfiConverterString.lower(`screenJson`),
                    _status,
                )
            }
        }

    /**
     * Navigate back in the history stack.
     *
     * Returns the previous screen model as JSON.
     */
    @Throws(MobileException::class)
    override fun `navigateBackJson`(): kotlin.String =
        FfiConverterString.lift(
            callWithPointer {
                uniffiRustCallWithError(MobileException) { _status ->
                    UniffiLib.INSTANCE.uniffi_vauchi_platform_fn_method_platformappengine_navigate_back_json(it, _status)
                }
            },
        )

    /**
     * Navigate to a screen (as JSON) and return the new screen model as JSON.
     *
     * The screen JSON must match the `AppScreen` enum format, e.g.:
     * - `"Exchange"` (simple variant)
     * - `{"ContactDetail": {"contact_id": "abc"}}` (parameterized variant)
     */
    @Throws(MobileException::class)
    override fun `navigateToJson`(`screenJson`: kotlin.String): kotlin.String =
        FfiConverterString.lift(
            callWithPointer {
                uniffiRustCallWithError(MobileException) { _status ->
                    UniffiLib.INSTANCE.uniffi_vauchi_platform_fn_method_platformappengine_navigate_to_json(
                        it,
                        FfiConverterString.lower(`screenJson`),
                        _status,
