    /**
     * Report device hardware capabilities.
     *
     * Call once at startup after querying platform hardware APIs.
     * Determines which exchange modes are available.
     */
    @Throws(MobileException::class)
    override fun `setDeviceCapabilitiesJson`(`capabilitiesJson`: kotlin.String) =
        callWithPointer {
            uniffiRustCallWithError(MobileException) { _status ->
                UniffiLib.INSTANCE.uniffi_vauchi_platform_fn_method_platformappengine_set_device_capabilities_json(
                    it,
