    override fun allocationSize(value: MobileAnimatedQrConfig) =
        (
            FfiConverterUByte.allocationSize(value.`fps`) +
                FfiConverterUInt.allocationSize(value.`chunkSize`) +
                FfiConverterUByte.allocationSize(value.`cyclePadding`)
