            }

            is MobileBleState.Failed -> {
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                (
                    4UL +
                        FfiConverterString.allocationSize(value.`error`)
                )
            }
        }

    override fun write(
        value: MobileBleState,
        buf: ByteBuffer,
    ) {
        when (value) {
            is MobileBleState.Connecting -> {
                buf.putInt(1)
                Unit
            }

            is MobileBleState.Handshaking -> {
                buf.putInt(2)
                Unit
            }

            is MobileBleState.Transferring -> {
                buf.putInt(3)
                Unit
            }

            is MobileBleState.Verifying -> {
                buf.putInt(4)
                Unit
            }

            is MobileBleState.Complete -> {
                buf.putInt(5)
                Unit
            }

            is MobileBleState.Failed -> {
                buf.putInt(6)
                FfiConverterString.write(value.`error`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}

