    data class BleCharacteristicNotified(
        val `uuid`: kotlin.String,
        val `data`: kotlin.ByteArray,
    ) : MobileExchangeHardwareEvent() {
        companion object
    }

    data class BleDisconnected(
        val `reason`: kotlin.String,
    ) : MobileExchangeHardwareEvent() {
