    ) : MobileExchangeHardwareEvent() {
        companion object
    }

    data class HardwareError(
        val `transport`: kotlin.String,
        val `error`: kotlin.String,
    ) : MobileExchangeHardwareEvent() {
        companion object
    }

    data class HardwareUnavailable(
        val `transport`: kotlin.String,
    ) : MobileExchangeHardwareEvent() {
        companion object
    }

    companion object
}

