/**
 * Mobile-friendly exchange state (no raw bytes or core types).
 */
sealed class MobileExchangeState {
    object Idle : MobileExchangeState()

    data class DisplayingQr(
        val `qrData`: kotlin.String,
    ) : MobileExchangeState() {
        companion object
    }

    object PeerScanned : MobileExchangeState()

    object AwaitingKeyAgreement : MobileExchangeState()

    object AwaitingCardExchange : MobileExchangeState()

    data class Complete(
        val `contactId`: kotlin.String,
        val `contactName`: kotlin.String,
    ) : MobileExchangeState() {
        companion object
    }

    data class Failed(
        val `error`: kotlin.String,
    ) : MobileExchangeState() {
        companion object
    }

    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeMobileExchangeState : FfiConverterRustBuffer<MobileExchangeState> {
    override fun read(buf: ByteBuffer): MobileExchangeState =
        when (buf.getInt()) {
            1 -> {
                MobileExchangeState.Idle
            }

            2 -> {
                MobileExchangeState.DisplayingQr(
                    FfiConverterString.read(buf),
                )
            }

            3 -> {
                MobileExchangeState.PeerScanned
            }

            4 -> {
                MobileExchangeState.AwaitingKeyAgreement
            }

            5 -> {
                MobileExchangeState.AwaitingCardExchange
            }

            6 -> {
                MobileExchangeState.Complete(
                    FfiConverterString.read(buf),
                    FfiConverterString.read(buf),
                )
            }

            7 -> {
                MobileExchangeState.Failed(
