/**
 * Error type for NFC transport callback interface.
 */
sealed class MobileNfcTransportException : kotlin.Exception() {
    class TransportFailed(
        val `msg`: kotlin.String,
    ) : MobileNfcTransportException() {
        override val message
            get() = "msg=${ `msg` }"
    }

    class TagLost : MobileNfcTransportException() {
        override val message
            get() = ""
    }

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<MobileNfcTransportException> {
        override fun lift(error_buf: RustBuffer.ByValue): MobileNfcTransportException =
            FfiConverterTypeMobileNfcTransportError.lift(error_buf)
