/**
 * Events emitted during proximity verification for mobile UI consumption.
 *
 * The mobile platform layer observes these to update the user interface:
 * - Show instructions ("Tap the table with both phones")
 * - Show progress bars
 * - Indicate method failures and fallbacks
 * - Announce completion with confidence level
 */
sealed class MobileProximityVerifierEvent {
    /**
     * Waiting for user action before verification can proceed.
     */
    data class WaitingForAction(
        val `method`: MobileVerifierMethod,
        val `instruction`: kotlin.String,
    ) : MobileProximityVerifierEvent() {
        companion object
    }

    /**
     * Verification is in progress for the given method.
     */
    data class InProgress(
        val `method`: MobileVerifierMethod,
        /**
         * 0–100 percent.
         */
        val `progressPct`: kotlin.UByte,
    ) : MobileProximityVerifierEvent() {
        companion object
    }

    /**
     * A verification method failed.
     */
    data class MethodFailed(
        val `method`: MobileVerifierMethod,
        val `reason`: kotlin.String,
    ) : MobileProximityVerifierEvent() {
        companion object
    }

    /**
     * Falling back from one method to another.
     */
    data class FallingBack(
        val `failedMethod`: MobileVerifierMethod,
        val `nextMethod`: MobileVerifierMethod,
    ) : MobileProximityVerifierEvent() {
        companion object
    }

    /**
     * Verification completed successfully.
     */
    data class Completed(
        val `method`: MobileVerifierMethod,
        val `confidence`: MobileProximityConfidence,
    ) : MobileProximityVerifierEvent() {
        companion object
    }

    /**
     * All available methods have been tried and failed.
     */
    object AllMethodsExhausted : MobileProximityVerifierEvent()

    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeMobileProximityVerifierEvent : FfiConverterRustBuffer<MobileProximityVerifierEvent> {
    override fun read(buf: ByteBuffer): MobileProximityVerifierEvent =
        when (buf.getInt()) {
            1 -> {
                MobileProximityVerifierEvent.WaitingForAction(
                    FfiConverterTypeMobileVerifierMethod.read(buf),
                    FfiConverterString.read(buf),
                )
            }

            2 -> {
                MobileProximityVerifierEvent.InProgress(
                    FfiConverterTypeMobileVerifierMethod.read(buf),
                    FfiConverterUByte.read(buf),
                )
            }

            3 -> {
                MobileProximityVerifierEvent.MethodFailed(
                    FfiConverterTypeMobileVerifierMethod.read(buf),
                    FfiConverterString.read(buf),
                )
            }

            4 -> {
                MobileProximityVerifierEvent.FallingBack(
                    FfiConverterTypeMobileVerifierMethod.read(buf),
                    FfiConverterTypeMobileVerifierMethod.read(buf),
                )
            }

            5 -> {
                MobileProximityVerifierEvent.Completed(
                    FfiConverterTypeMobileVerifierMethod.read(buf),
                    FfiConverterTypeMobileProximityConfidence.read(buf),
                )
            }

            6 -> {
                MobileProximityVerifierEvent.AllMethodsExhausted
            }

            else -> {
                throw RuntimeException("invalid enum value, something is very wrong!!")
            }
        }

    override fun allocationSize(value: MobileProximityVerifierEvent) =
        when (value) {
            is MobileProximityVerifierEvent.WaitingForAction -> {
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                (
                    4UL +
                        FfiConverterTypeMobileVerifierMethod.allocationSize(value.`method`) +
                        FfiConverterString.allocationSize(value.`instruction`)
                )
            }

            is MobileProximityVerifierEvent.InProgress -> {
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                (
                    4UL +
                        FfiConverterTypeMobileVerifierMethod.allocationSize(value.`method`) +
                        FfiConverterUByte.allocationSize(value.`progressPct`)
                )
            }

            is MobileProximityVerifierEvent.MethodFailed -> {
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                (
                    4UL +
                        FfiConverterTypeMobileVerifierMethod.allocationSize(value.`method`) +
                        FfiConverterString.allocationSize(value.`reason`)
                )
            }

            is MobileProximityVerifierEvent.FallingBack -> {
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                (
                    4UL +
                        FfiConverterTypeMobileVerifierMethod.allocationSize(value.`failedMethod`) +
                        FfiConverterTypeMobileVerifierMethod.allocationSize(value.`nextMethod`)
                )
            }

            is MobileProximityVerifierEvent.Completed -> {
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                (
                    4UL +
                        FfiConverterTypeMobileVerifierMethod.allocationSize(value.`method`) +
                        FfiConverterTypeMobileProximityConfidence.allocationSize(value.`confidence`)
                )
            }

            is MobileProximityVerifierEvent.AllMethodsExhausted -> {
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                (
                    4UL
                )
            }
        }

    override fun write(
        value: MobileProximityVerifierEvent,
        buf: ByteBuffer,
    ) {
        when (value) {
            is MobileProximityVerifierEvent.WaitingForAction -> {
                buf.putInt(1)
                FfiConverterTypeMobileVerifierMethod.write(value.`method`, buf)
                FfiConverterString.write(value.`instruction`, buf)
                Unit
            }

            is MobileProximityVerifierEvent.InProgress -> {
                buf.putInt(2)
                FfiConverterTypeMobileVerifierMethod.write(value.`method`, buf)
                FfiConverterUByte.write(value.`progressPct`, buf)
                Unit
            }

            is MobileProximityVerifierEvent.MethodFailed -> {
                buf.putInt(3)
                FfiConverterTypeMobileVerifierMethod.write(value.`method`, buf)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }

            is MobileProximityVerifierEvent.FallingBack -> {
                buf.putInt(4)
                FfiConverterTypeMobileVerifierMethod.write(value.`failedMethod`, buf)
                FfiConverterTypeMobileVerifierMethod.write(value.`nextMethod`, buf)
                Unit
            }

            is MobileProximityVerifierEvent.Completed -> {
                buf.putInt(5)
                FfiConverterTypeMobileVerifierMethod.write(value.`method`, buf)
                FfiConverterTypeMobileProximityConfidence.write(value.`confidence`, buf)
                Unit
            }

            is MobileProximityVerifierEvent.AllMethodsExhausted -> {
                buf.putInt(6)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}

/**
 * Current shred status for the identity.
 */
sealed class MobileShredStatus {
    /**
     * No shred operation in progress.
     */
    object None : MobileShredStatus()

    /**
     * Soft shred scheduled — waiting for grace period to elapse.
     */
    data class Scheduled(
        /**
         * Seconds remaining in grace period.
         */
        val `remainingSecs`: kotlin.ULong,
    ) : MobileShredStatus() {
        companion object
    }

    /**
     * Hard shred has been executed — all data destroyed.
     */
    object Executed : MobileShredStatus()

    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeMobileShredStatus : FfiConverterRustBuffer<MobileShredStatus> {
    override fun read(buf: ByteBuffer): MobileShredStatus =
        when (buf.getInt()) {
            1 -> {
                MobileShredStatus.None
            }

            2 -> {
                MobileShredStatus.Scheduled(
                    FfiConverterULong.read(buf),
                )
            }

            3 -> {
                MobileShredStatus.Executed
            }

            else -> {
                throw RuntimeException("invalid enum value, something is very wrong!!")
            }
        }

    override fun allocationSize(value: MobileShredStatus) =
        when (value) {
            is MobileShredStatus.None -> {
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                (
                    4UL
                )
            }

            is MobileShredStatus.Scheduled -> {
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                (
                    4UL +
                        FfiConverterULong.allocationSize(value.`remainingSecs`)
                )
            }

            is MobileShredStatus.Executed -> {
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                (
                    4UL
                )
            }
        }

    override fun write(
        value: MobileShredStatus,
        buf: ByteBuffer,
    ) {
        when (value) {
            is MobileShredStatus.None -> {
                buf.putInt(1)
                Unit
            }

            is MobileShredStatus.Scheduled -> {
                buf.putInt(2)
                FfiConverterULong.write(value.`remainingSecs`, buf)
                Unit
            }

            is MobileShredStatus.Executed -> {
                buf.putInt(3)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}

